import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';
import {hash,json} from './bounded-source-hash-20261026.mjs';import {guarded} from './run-small-native-task-guarded-20261025.mjs';
const [state,indexArg,expectedPlanSha]=process.argv.slice(2);assert.equal(process.argv.length,5);assert(/^\d+$/.test(indexArg));assert(/^[0-9a-f]{64}$/.test(expectedPlanSha));
assert(path.resolve(state).startsWith(path.resolve('F:/VisibleMedicine/staging')+path.sep));
const sourceFile='F:/VisibleMedicine/staging/20261026-current-delivery-advance/SOURCE_CANDIDATE.json',sourceSha='9da49fa0b687608c86fdee92459eb3693b39426789fbe6e86595f1ff18a03e43',source=json(sourceFile),dir=state+'/guard-'+indexArg;
const driverDir='F:/VisibleMedicine/staging/20261026-current-bounded-campaign-driver',adapterFile=driverDir+'/ADAPTER.json',adapterSha=hash(adapterFile),adapter=json(adapterFile),index=Number(indexArg);
function verify(){assert.equal(hash(sourceFile),sourceSha);assert.equal(hash(state+'/PLAN.json'),expectedPlanSha);assert.equal(hash(adapterFile),adapterSha);assert.equal(hash(adapter.driver.path),adapter.driver.sha256);assert.equal(hash(adapter.reporter.path),adapter.reporter.sha256);for(const r of source.sourceRows)assert.equal(hash(source.website+'/'+r.path),r.sha256,r.path);for(const d of source.dependencies){assert.equal(hash(d.file),d.sha256);assert.equal(hash(d.entry),d.entrySha256);}const git=args=>execFileSync('git',['-C',source.atlas,...args],{encoding:'utf8',windowsHide:true}).trim();assert.equal(git(['rev-parse','HEAD']),source.atlasHead);assert.equal(git(['rev-parse','HEAD^{tree}']),source.atlasTree);assert.equal(git(['status','--porcelain']),'');}
verify();assert(!fs.existsSync(dir));assert(!fs.existsSync(state+'/shard-'+String(index).padStart(3,'0')));
const initial=json('CURRENT_CHECKPOINT.json');assert.deepEqual(initial.activeWork.current.activeExecutionSessions,[]);assert.equal(initial.activeWork.current.ownerPreviewPolicy.restartPermitted,false);
initial.activeWork.current.activeExecutionSessions=[{kind:'bounded-whole-stock-shard-diagnostic',driverPid:process.pid,sourceSha256:sourceSha,evidence:dir,campaign:state,index,planSha256:expectedPlanSha}];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(initial,null,2)+'\n');
process.once('exit',code=>{if(code!==75||fs.existsSync(dir))return;const j=json('CURRENT_CHECKPOINT.json');if(j.activeWork.current.activeExecutionSessions[0]?.driverPid!==process.pid)return;fs.writeFileSync(dir+'-ADMISSION_REFUSAL.json',JSON.stringify({at:new Date().toISOString(),code,noProcessStarted:true,sourceSha256:sourceSha,planSha256:expectedPlanSha},null,2)+'\n',{flag:'wx'});j.activeWork.current.activeExecutionSessions=[];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(j,null,2)+'\n');});
try{global.gc();const run=await guarded({site:source.website,dir,command:'--max-old-space-size=1024 '+adapter.driver.path+' run-shard '+state+' '+indexArg+' '+expectedPlanSha,heap:1024,aggregate:2048,minimum:4096,extraEnv:{VM_ATLAS_SOURCE_REPO:source.atlas,ATLAS_SOURCE_REPO:source.atlas,VM_ATLAS_ACCESS_SQL_ROOT:source.website}});verify();const terminalFile=state+'/shard-'+String(index).padStart(3,'0')+'/TERMINAL.json',terminal=fs.existsSync(terminalFile)?json(terminalFile):null;const result={at:new Date().toISOString(),source:{path:sourceFile,sha256:sourceSha},adapter:{path:adapterFile,sha256:adapterSha},plan:{path:state+'/PLAN.json',sha256:expectedPlanSha},run,terminal:terminal?{path:terminalFile,sha256:hash(terminalFile)}:null,counts:terminal?.counts??null,passingForThisShardOnly:run.passing&&terminal?.passingClaim===true,allSealedSourceAndNativeAndNamedDependenciesStillExact:true,stockSuitePassingClaim:false,normalPreviewChanged:false};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({path:dir+'/RESULT.json',sha256:hash(dir+'/RESULT.json'),terminal:result.terminal,counts:result.counts,passingForThisShardOnly:result.passingForThisShardOnly}));process.exitCode=terminal?0:1;}finally{const j=json('CURRENT_CHECKPOINT.json');assert.equal(j.activeWork.current.activeExecutionSessions[0]?.driverPid,process.pid);j.activeWork.current.activeExecutionSessions=[];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(j,null,2)+'\n');}
